        p50.push(Math.round(median));
        p95.push(Math.round(tail95));
        p99.push(Math.round(tail99));
    }

    return {
        timestamps,
        series: [
            {id: 'p50', name: 'p50, мс', values: p50},
            {id: 'p95', name: 'p95, мс', values: p95},
            {id: 'p99', name: 'p99, мс', values: p99},
        ],
    };
}

